mapper.insert:
INSERT INTO notification_outbox (
    event_id, notification_id, campaign_id, dedupe_key, available_at
) VALUES (
    #{eventId}, #{notificationId}, #{campaignId}, #{dedupeKey}, #{availableAt}
)
ON DUPLICATE KEY UPDATE outbox_id = LAST_INSERT_ID(outbox_id)

mapper.select:
SELECT outbox_id, event_id, notification_id, campaign_id, dedupe_key, status,
       publish_attempts, available_at, claimed_at, published_at, last_error,
       created_at, updated_at
FROM notification_outbox
WHERE status IN ('PENDING', 'FAILED')
  AND available_at <= #{now}
  AND publish_attempts < #{maxAttempts}
ORDER BY outbox_id
LIMIT #{limit}
FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE notification_outbox
SET status = 'FAILED''PENDING',
    available_at = #{availableAt},
    last_error = #{lastError}
WHERE outbox_id = #{outboxId}
